/// Returns the last occurrence index of `cafe` in `cafes`.
/// Assumes that `cafe` does appear in `cafes`.
fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Scan from the end backwards until we find `cafe`.
    for (i, &v) in cafes.iter().enumerate().rev() {
        if v == cafe {
            return i;
        }
    }
    // According to the problem statement, `cafe` is guaranteed to be in the array,
    // so we should never reach here.
    unreachable!("Value {} not found in array", cafe);
}

/// Given a non-empty vector of i8 values, returns one value whose last
/// occurrence in the array is as early as possible.
fn solve(cafes: Vec<i8>) -> i8 {
    // Build a map from each cafe value to its last occurrence index.
    let mut last_occ: HashMap<i8, usize> = HashMap::new();
    for (i, &v) in cafes.iter().enumerate() {
        last_occ.insert(v, i);
    }

    // Initialize with the first element's last occurrence.
    let mut best_val = cafes[0];
    let mut best_pos = *last_occ.get(&best_val).unwrap();

    // Find the value with the minimal last-occurrence index.
    for (&val, &pos) in last_occ.iter() {
        if pos < best_pos {
            best_pos = pos;
            best_val = val;
        }
    }

    best_val
}

